import atlasUrl from '../../public/art/bestiary-v3.png?url';
import * as T from 'three';
import {DungeonView} from './dungeon-view.js';
import {HEROES,MONSTERS,REGIONS} from './roster.js';
export class Scene{
 constructor(canvas){
 this.renderer=new T.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});this.mobile=matchMedia('(pointer:coarse)').matches;this.renderer.setPixelRatio(Math.min(devicePixelRatio,this.mobile?1.25:1.5));this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.15;this.scene=new T.Scene();this.scene.background=new T.Color(0x111716);this.scene.fog=new T.FogExp2(0x111716,.018);this.camera=new T.OrthographicCamera();this.scene.add(new T.HemisphereLight(0xb6c3bb,0x292016,2));this.sun=new T.DirectionalLight(0xe3d2af,2.1);this.sun.position.set(-10,24,8);this.scene.add(this.sun);this.dungeon=new DungeonView(this.scene);this.temp=new T.Object3D();this.color=new T.Color();
 const texture=new T.TextureLoader().load(atlasUrl);texture.colorSpace=T.SRGBColorSpace;texture.minFilter=T.LinearMipmapLinearFilter;texture.magFilter=T.LinearFilter;this.texture=texture;
 const geometry=new T.PlaneGeometry(1,1,8,8);this.tile=new T.InstancedBufferAttribute(new Float32Array(256),1);this.pose=new T.InstancedBufferAttribute(new Float32Array(256*4),4);geometry.setAttribute('tile',this.tile);geometry.setAttribute('pose',this.pose);
 const material=new T.MeshBasicMaterial({map:texture,transparent:true,alphaTest:.12,depthWrite:true,side:T.DoubleSide});material.onBeforeCompile=shader=>{shader.vertexShader='attribute float tile; attribute vec4 pose; varying vec4 vPose;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <uv_vertex>','#include <uv_vertex>\n vMapUv = vec2((mod(tile,8.0)+0.015+uv.x*0.97)/8.0,(3.0-floor(tile/8.0)+0.015+uv.y*0.97)/4.0); vPose=pose;');shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\n float upper=smoothstep(-0.4,0.4,position.y); transformed.x += sin(pose.x+position.y*3.0)*pose.y*upper; transformed.y += sin(pose.x+sign(position.x)*1.57)*pose.y*(1.0-upper)*0.45;');shader.fragmentShader='varying vec4 vPose;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\n diffuseColor.rgb=mix(diffuseColor.rgb,vec3(1.0,0.85,0.65),vPose.z); diffuseColor.a*=vPose.w;');};this.actors=new T.InstancedMesh(geometry,material,256);this.actors.frustumCulled=false;this.scene.add(this.actors);
 this.shadows=new T.InstancedMesh(new T.CircleGeometry(.5,20),new T.MeshBasicMaterial({color:0x050807,transparent:true,opacity:.35,depthWrite:false}),256);this.shadows.frustumCulled=false;this.scene.add(this.shadows);
 this.particles=new T.InstancedMesh(new T.SphereGeometry(1,6,4),new T.MeshBasicMaterial(),600);this.particles.frustumCulled=false;this.scene.add(this.particles);
 this.rings=new T.InstancedMesh(new T.RingGeometry(.91,1,48),new T.MeshBasicMaterial({transparent:true,opacity:.7,side:T.DoubleSide,depthWrite:false}),180);this.rings.frustumCulled=false;this.scene.add(this.rings);this.resize();window.addEventListener('resize',()=>this.resize());this.lastBiome=-1;
 }
 resize(){const w=innerWidth,h=innerHeight,half=this.mobile?11:10;this.camera.left=-half*w/h;this.camera.right=half*w/h;this.camera.top=half;this.camera.bottom=-half;this.camera.near=.1;this.camera.far=120;this.camera.updateProjectionMatrix();this.renderer.setSize(w,h);}
 draw(game,time,hero='cinder',reduced=false){const p=game?.player||{x:0,z:0,dx:0,dz:1,moving:false,attack:0,dash:0},biome=game?.biome||0;const t=game?.time||time;this.camera.position.set(p.x,27,p.z+22);this.camera.lookAt(p.x,0,p.z);this.dungeon.update(p,reduced?0:t,biome,reduced);
 if(this.lastBiome!==biome){this.lastBiome=biome;this.dungeon.floorMaterial.color.setHex([0xaaa592,0x829e99,0x989b78][biome]);this.scene.fog.color.setHex(REGIONS[biome].ground).multiplyScalar(.45);this.scene.background.copy(this.scene.fog.color);}
 let actor=0,shadow=0,particle=0,ring=0;
 const sprite=(entity,tile,size,dead=false)=>{if(actor>=256)return;const moving=entity.moving??true,attack=entity.attack>0,hit=entity.flash>0;const state=dead?'death':entity.dash?'dodge':hit?'hit':attack?'attack':moving?'run':'idle';const phase=reduced?0:t*(state==='run'?14:4)+entity.id*.3||t*4;const flip=entity.dx<-.1?-1:1;let lean=state==='dodge'?.35*flip:state==='attack'?-.12*flip:0;this.temp.position.set(entity.x,size*.47+(state==='run'&&!reduced?Math.abs(Math.sin(phase))*.055:0),entity.z);this.temp.quaternion.copy(this.camera.quaternion);this.temp.rotateZ(lean+(dead?(1-(entity.life??.65)/.65)*1.2:0));this.temp.scale.set(size*flip,size*(state==='dodge'?.82:1),1);this.temp.updateMatrix();this.actors.setMatrixAt(actor,this.temp.matrix);this.tile.setX(actor,tile);this.pose.setXYZW(actor,phase,reduced?0:state==='run'?.045:state==='attack'?.07:.009,hit?.6:0,dead?Math.max(0,(entity.life??.65)/.65):1);actor++;
 this.temp.position.set(entity.x,.04,entity.z);this.temp.rotation.set(-Math.PI/2,0,0);this.temp.scale.set(size*.55,size*.32,1);this.temp.updateMatrix();this.shadows.setMatrixAt(shadow++,this.temp.matrix);};
 const marker=(x,z,r,color)=>{if(ring>=180)return;this.temp.position.set(x,.07,z);this.temp.rotation.set(-Math.PI/2,0,0);this.temp.scale.setScalar(r);this.temp.updateMatrix();this.rings.setMatrixAt(ring,this.temp.matrix);this.rings.setColorAt(ring++,this.color.setHex(color));};
 const spark=(x,y,z,size,color,elongate=1,angle=0)=>{if(particle>=600)return;this.temp.position.set(x,y,z);this.temp.rotation.set(0,angle,0);this.temp.scale.set(size,size,size*elongate);this.temp.updateMatrix();this.particles.setMatrixAt(particle,this.temp.matrix);this.particles.setColorAt(particle++,this.color.setHex(color));};
 sprite(p,HEROES[game?.hero||hero].sprite,2.8,game?.state==='dead');marker(p.x,p.z,.6,0xbba880);
 for(const e of game?.enemies||[]){sprite(e,MONSTERS[e.type].sprite,e.boss?4.6:e.elite?3.1:2.5);if(e.windup>0){marker(e.x,e.z,e.behavior==='pulse'?3:e.behavior==='boss'?4:1.35,0xe79562);if(e.behavior==='charge')for(let i=1;i<6;i++)marker(e.x+Math.sin(e.aim)*i,e.z+Math.cos(e.aim)*i,.25,0xe79562);}if(e.elite)marker(e.x,e.z,.8,0xd1ac58);}
 for(const e of game?.corpses||[])sprite(e,MONSTERS[e.type].sprite,e.boss?4.6:2.5,true);
 for(const l of game?.loot||[]){sprite({...l,dx:0,moving:false},l.kind==='xp'?29:l.kind==='potion'?30:31,l.kind==='xp'?.45:l.kind==='chest'?1:.65);}
 const color=parseInt(HEROES[game?.hero||hero].color.slice(1),16);
 for(const b of game?.bolts||[])spark(b.x,.65,b.z,b.enemy?.13:.1,b.enemy?0xe08a69:color,b.kind==='arrow'?5:2,Math.atan2(b.vx,b.vz));
 for(const z of game?.zones||[])marker(z.x,z.z,z.radius,z.enemy?(z.warn>0?0xd9b471:0xb65b44):0xa4b16a);
 for(const e of game?.effects||[]){marker(e.x,e.z,e.radius*(1-e.life/.7),e.color);if(!reduced)for(let i=0;i<5;i++){const a=i*2.399+e.id;const d=(.45-e.life)*5;spark(e.x+Math.sin(a)*d,.3+Math.sin(e.life*6)*.7,e.z+Math.cos(a)*d,.035,e.color);}}
 for(const [mesh,count]of[[this.actors,actor],[this.shadows,shadow],[this.particles,particle],[this.rings,ring]]){mesh.count=count;mesh.instanceMatrix.needsUpdate=true;if(mesh.instanceColor)mesh.instanceColor.needsUpdate=true;}this.tile.needsUpdate=true;this.pose.needsUpdate=true;this.renderer.render(this.scene,this.camera);
 }
}
